fn split_inside_pair(items: &[HistoryItem], split: usize) -> Option<usize> {
    let mut earliest: Option<usize> = None;
    // 输出下标 → 对应调用下标；档案与历史里输出总在调用之后。
    let mut pending: HashMap<&str, usize> = HashMap::new();
    for (index, item) in items.iter().enumerate() {
        match item {
            HistoryItem::FunctionCall { call_id, .. } => {
                pending.insert(call_id.as_str(), index);
            }
            HistoryItem::FunctionCallOutput { call_id, .. } => {
                if let Some(&call_index) = pending.get(call_id.as_str()) {
                    if call_index < split && index >= split {
                        earliest = Some(earliest.map_or(call_index, |cur: usize| cur.min(call_index)));
                    }
                }
            }
        }
    }
    earliest
}
```

