1103:     slots: &mut Vec<Slot>,
1104:     range_start: usize,
1105:     range_end: usize,
1106:     summary: SessionEntry,
1107: ) -> Result<(), String> {
1108:     let history_len = slots.iter().filter(|slot| slot.is_history()).count();
1109:     if range_start > range_end || range_end > history_len {
1110:         return Err(format!(
1111:             "压缩锚点区间 [{range_start},{range_end}) 超出已重放长度 {history_len}"
1112:         ));
1113:     }
1114:     let Some(first) = history_position(slots, range_start) else {
1115:         // 空档案上的空区间：等价于在末尾插一条摘要（resume 的 splice 同结果）。
1116:         slots.push(Slot::Summary(summary));
1117:         return Ok(());
1118:     };
1119:     let mut index = first;
1120:     let mut remaining = range_end - range_start;
1121:     while remaining > 0 {
1122:         if slots[index].is_history() {
1123:             slots.remove(index);
1124:             remaining -= 1;
1125:         } else {
1126:             // 夹在区间里的 TurnEnd 是审计记录：不占序号，也不该被吞掉。
1127:             index += 1;
1128:         }
1129:     }
1130:     slots.insert(first, Slot::Summary(summary));
1131:     Ok(())
